-- Migration: Question generation — REG batch 22 (30 questions)
-- Date: 2026-02-28
-- Topic: Tax-Exempt Organizations
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Section 501(h) expenditure test election for lobbying
(3, 'Tax-Exempt Organizations', 'Bright Horizons Education, a 501(c)(3) public charity with exempt purpose expenditures of $600,000, elects the Section 501(h) expenditure test. It spends $80,000 on direct lobbying and $25,000 on grassroots lobbying during the year. Under the 501(h) safe harbor thresholds, how should the organization evaluate its lobbying activity?', '["The organization is within both the overall and grassroots lobbying limits", "The organization exceeds the overall lobbying limit because total spending is $105,000", "The organization exceeds the grassroots lobbying limit of $15,000", "The 501(h) election is unavailable because exempt purpose expenditures exceed $500,000"]'::jsonb, 0, 'Under Section 501(h), the overall lobbying limit for $600,000 of exempt purpose expenditures is $115,000 (20% of first $500,000 plus 15% of next $100,000), and the grassroots limit is 25% of $115,000 ($28,750). Total lobbying of $105,000 and grassroots of $25,000 are both within limits. Choice C incorrectly calculates the grassroots limit — it is 25% of the overall lobbying ceiling, not 15% of exempt purpose expenditures.', 'medium', 3),

-- Q2: medium / L3 — Controlled entity payments (80% owned subsidiary) UBIT
(3, 'Tax-Exempt Organizations', 'Cedar Valley Library, a 501(c)(3), owns 90% of the voting stock of PageTurn Enterprises, a taxable corporation. PageTurn pays Cedar Valley $200,000 annually in rent for use of a building. The fair market value of the rental is $150,000. Under the controlled entity rules, how is the $200,000 in rent treated for UBIT purposes?', '["The entire $200,000 is excluded from UBIT as passive rental income", "The $50,000 excess over fair market value is included in UBIT", "The entire $200,000 is included in UBIT because it comes from a controlled entity", "Only $150,000 is included in UBIT because that is the fair market value portion"]'::jsonb, 1, 'Under IRC Section 512(b)(13), rent received from a controlled entity (80% or more ownership) is treated as UBIT to the extent it exceeds fair market value. Since PageTurn pays $200,000 but FMV is $150,000, the $50,000 excess is included in UBIT. Choice C is incorrect because only the amount exceeding FMV is subject to UBIT, not the entire payment from the controlled subsidiary.', 'medium', 3),

-- Q3: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What must a 501(c)(3) organization''s governing documents include regarding asset distribution upon dissolution?', '["A provision distributing assets equally among the organization''s members", "A clause directing assets to the organization''s officers and directors", "A provision distributing assets to another exempt organization or the government", "A clause returning assets to the original donors"]'::jsonb, 2, 'Under Section 501(c)(3), the organizational test requires a dissolution clause directing assets to another exempt organization or to a government entity upon dissolution. This ensures that assets dedicated to charitable purposes remain in charitable use. Choice A is incorrect because distribution to members would constitute private inurement, violating the 501(c)(3) requirements.', 'easy', 1),

-- Q4: medium / L3 — Convenience exclusion for UBIT
(3, 'Tax-Exempt Organizations', 'Northgate Medical Center, a 501(c)(3) hospital, operates a cafeteria on its premises that serves breakfast and lunch primarily to hospital employees, patients, and visitors. It also sells meals to members of the general public who walk in from the street. How does the convenience exclusion under Section 513(a)(2) apply to the cafeteria income?', '["All cafeteria income is subject to UBIT because food service is not related to medical care", "Only income from sales to patients is excluded because they are receiving medical services", "The exclusion applies only if the cafeteria operates at a loss", "The convenience exclusion generally applies because the cafeteria is operated primarily for employees and patients, even though some public sales occur"]'::jsonb, 3, 'Under Section 513(a)(2), income from a trade or business carried on primarily for the convenience of members, students, patients, officers, or employees is excluded from UBIT. A hospital cafeteria serving primarily staff and patients qualifies, even with incidental public sales. Choice A is incorrect because the convenience exclusion applies regardless of whether the activity relates to the exempt purpose — it is a separate statutory exclusion.', 'medium', 3),

-- Q5: hard / L3 — Acquisition indebtedness ratio calculation (Section 514)
(3, 'Tax-Exempt Organizations', 'Riverside Scholarship Fund, a 501(c)(3), borrows $600,000 to purchase an office building for $1,000,000, renting it to commercial tenants. At year-end, the average acquisition indebtedness is $540,000 and the average adjusted basis of the property is $900,000. Gross rental income is $120,000 with $45,000 in directly connected expenses. What is the unrelated debt-financed income subject to UBIT under Section 514?', '["$45,000", "$72,000", "$75,000", "$120,000"]'::jsonb, 0, 'Under Section 514, debt-financed income is taxable in proportion to the average acquisition indebtedness divided by the average adjusted basis. The ratio is $540,000/$900,000 = 60%. Gross income subject to UBIT is $120,000 x 60% = $72,000, and deductible expenses are $45,000 x 60% = $27,000, yielding net debt-financed income of $45,000. Choice B incorrectly omits the proportional expense deduction from the calculation.', 'hard', 3),

-- Q6: medium / L3 — Research exclusion from UBIT (non-university)
(3, 'Tax-Exempt Organizations', 'Heritage Science Foundation, a 501(c)(3) research organization (not a college, university, or hospital), performs contract research for three clients: $200,000 for a federal government agency, $150,000 for a private pharmaceutical company under a proprietary contract, and $100,000 for a study whose results are freely published to the general public. Which portion of the research income is excluded from UBIT?', '["Only the $200,000 from the federal government contract", "$300,000 from the government contract and the publicly available research", "All $450,000 because any research by a 501(c)(3) organization is excluded", "$350,000 from the government and pharmaceutical contracts"]'::jsonb, 1, 'Under Section 512(b)(7), research for the U.S. government is excluded from UBIT. Under Section 512(b)(9), research whose results are freely available to the public is also excluded. The $200,000 government contract and $100,000 public research qualify, totaling $300,000. The $150,000 proprietary contract does not qualify because the foundation is not a college, university, or hospital (which would qualify under Section 512(b)(8)). Choice C incorrectly assumes all 501(c)(3) research is excluded.', 'medium', 3),

-- Q7: medium / L3 — Personal property rents (10% incidental rule)
(3, 'Tax-Exempt Organizations', 'Beacon Literacy Foundation, a 501(c)(3), leases a furnished office suite to a commercial tenant. The monthly rent is $10,000, of which $800 is allocable to the personal property (furniture and equipment) and $9,200 to the real property. Under the UBIT modifications for rental income, how is the total rent treated?', '["The entire $10,000 is included in UBIT as mixed rental income", "Only the $800 personal property portion is included in UBIT", "The entire $10,000 is excluded from UBIT because personal property rents are less than 10% of total rent", "The $9,200 real property portion is excluded but the $800 is subject to a separate excise tax"]'::jsonb, 2, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT. When a lease includes personal property, the personal property rent is included in UBIT unless it is incidental — defined as less than 10% of total rent. Since $800/$10,000 = 8% (below 10%), the entire $10,000 rent is excluded. Choice B is incorrect because the incidental personal property exception treats the entire rent as excluded when the personal property portion falls below the 10% threshold.', 'medium', 3),

-- Q8: easy / L1 — Churches/schools/hospitals as automatic public charities
(3, 'Tax-Exempt Organizations', 'Under Section 509, which type of 501(c)(3) organization is automatically classified as a public charity regardless of its funding sources?', '["A community foundation that receives donations from multiple donors", "A private operating foundation that conducts its own programs", "A supporting organization that operates exclusively for another charity", "A church, school, or hospital"]'::jsonb, 3, 'Under Section 509(a)(1) referencing Section 170(b)(1)(A), churches, schools, and hospitals are automatically classified as public charities regardless of their funding sources or public support percentages. They do not need to meet the one-third support test. Choice A is incorrect because a community foundation must demonstrate broad public support to qualify — it is not automatically classified as a public charity.', 'easy', 1),

-- Q9: medium / L2 — Form 990-PF for all private foundations
(3, 'Tax-Exempt Organizations', 'Sterling Family Foundation, a private foundation with $50,000 in gross receipts and $200,000 in total assets, prepares to file its annual information return with the IRS. Which form must the foundation file?', '["Form 990-PF regardless of the foundation''s size", "Form 990-EZ because gross receipts are under $200,000 and total assets are under $500,000", "Form 990-N (e-Postcard) because gross receipts are $50,000 or less", "Form 990 because total assets exceed $100,000"]'::jsonb, 0, 'Under IRC Section 6033, all private foundations must file Form 990-PF regardless of their gross receipts or total assets. The size-based thresholds for Form 990, 990-EZ, and 990-N apply only to public charities and other exempt organizations. Choice B is incorrect because the 990-EZ option is not available to private foundations — they must file the more detailed 990-PF with excise tax computations.', 'medium', 2),

-- Q10: hard / L4 — Supporting organizations (Section 509(a)(3)) analysis
(3, 'Tax-Exempt Organizations', 'Crossroads Community Services, a 501(c)(3), is organized exclusively to raise funds for Lakewood Hospital, a 501(c)(3) public charity. Crossroads receives 80% of its funding from a single family, with 20% from small donations. Its board includes two hospital executives and three family members. Evaluate whether Crossroads qualifies as a public charity under Section 509(a)(3) and identify the most significant concern.', '["Crossroads qualifies as a Type I supporting organization, but the family-controlled board raises concerns about control by disqualified persons under Section 509(f)", "Crossroads cannot qualify because it receives more than one-third of support from a single family", "Crossroads automatically qualifies as a public charity because it exclusively supports a hospital", "Crossroads must meet the one-third public support test independently because supporting organizations cannot rely on their supported organization''s status"]'::jsonb, 0, 'Under Section 509(a)(3), a supporting organization must be organized and operated exclusively to support one or more public charities. However, Section 509(f) restricts supporting organizations controlled by donors, and IRS scrutiny applies when disqualified persons (the family) control the board. Crossroads may qualify but the majority-family board creates a significant control concern. Choice C is incorrect because merely supporting a public charity does not guarantee qualification — governance independence matters.', 'hard', 4),

-- Q11: hard / L4 — Section 4958 additional 200% tax for failure to correct
(3, 'Tax-Exempt Organizations', 'Summit Outreach, a 501(c)(3), pays its program director a $600,000 bonus on top of her $350,000 salary. Comparable compensation is $400,000. The IRS determines the excess benefit is $550,000. The program director does not correct the transaction within the taxable period. What is the total excise tax exposure for the program director under Section 4958?', '["$137,500 (25% initial tax only)", "$1,100,000 (200% additional tax only)", "$1,237,500 (25% initial tax plus 200% additional tax for failure to correct)", "$550,000 (return of the excess benefit amount)"]'::jsonb, 2, 'Under Section 4958, the initial tax on the disqualified person is 25% of the excess benefit ($550,000 x 25% = $137,500). If the transaction is not corrected within the taxable period, an additional tax of 200% ($550,000 x 200% = $1,100,000) applies, totaling $1,237,500. Choice A is incorrect because it omits the additional 200% tax imposed for failure to correct the excess benefit transaction within the required period.', 'hard', 4),

-- Q12: medium / L2 — One-third public support test (2% per-donor cap)
(3, 'Tax-Exempt Organizations', 'Greenleaf Conservation, a 501(c)(3), receives $400,000 in total support: $180,000 from government grants, $90,000 from individual small donors, $80,000 from investment income, and $50,000 from a single wealthy donor. Under the one-third support test of Section 509(a)(1), does Greenleaf qualify as a public charity?', '["No, because investment income of $80,000 disqualifies the organization", "No, because the $50,000 from a single donor exceeds the 2% limit and taints all public support", "Yes, because total receipts exceed $200,000", "Yes, because public support (government grants plus small donor contributions, with the large donor capped at 2% of total support) exceeds one-third"]'::jsonb, 3, 'Under Section 509(a)(1), public support includes government grants (fully) and contributions from the general public (each donor limited to 2% of total support). Government grants ($180,000) plus small donors ($90,000) plus the large donor (capped at $8,000 = 2% of $400,000) equals $278,000, which is 69.5% of total support — well above the one-third threshold. Choice B is incorrect because the 2% limit caps but does not disqualify the individual contribution.', 'medium', 2),

-- Q13: medium / L2 — Bingo game exclusion (Section 513(f))
(3, 'Tax-Exempt Organizations', 'Hope and Healing Center, a 501(c)(3), hosts weekly bingo games that generate $60,000 in annual net income. The games are legal under state law, and no commercial bingo halls operate in the jurisdiction. Are the bingo game proceeds subject to UBIT?', '["No, because bingo is excluded under Section 513(f) when it is legal and not ordinarily carried on commercially in the jurisdiction", "Yes, because bingo meets all three parts of the UBIT test", "Yes, unless substantially all the work is performed by volunteers", "No, but only if net proceeds are less than $50,000"]'::jsonb, 0, 'Under Section 513(f), bingo games are excluded from UBIT if the game is legal under state and local law and commercial bingo is not ordinarily carried out in the jurisdiction. Both conditions are met here, so the $60,000 is excluded. Choice C is incorrect because it confuses the bingo exclusion with the separate volunteer labor exclusion under Section 513(a)(1) — these are independent statutory exclusions.', 'medium', 2),

-- Q14: easy / L1 — Form 990-N (e-Postcard) threshold
(3, 'Tax-Exempt Organizations', 'Which IRS filing is required for a tax-exempt organization with annual gross receipts of $50,000 or less?', '["Form 990-EZ (simplified return)", "Form 990-N (e-Postcard)", "Form 990 (full annual return)", "No filing is required at this level"]'::jsonb, 1, 'Under IRC Section 6033, tax-exempt organizations with gross receipts normally $50,000 or less must file Form 990-N, an electronic notice (e-Postcard) providing basic identifying information. This simplified filing replaces the longer Form 990 or 990-EZ. Choice D is incorrect because failure to file any return for three consecutive years results in automatic revocation of exempt status under Section 6033(j).', 'easy', 1),

-- Q15: medium / L2 — Section 4945 taxable expenditure — grants to non-501(c)(3)
(3, 'Tax-Exempt Organizations', 'Whitmore Family Foundation, a private foundation, awards a $100,000 grant directly to a 501(c)(4) social welfare organization to fund community health programs. The foundation does not exercise expenditure responsibility over the grant. Under Section 4945, how is this grant treated?', '["The grant is permissible because the 501(c)(4) organization serves a charitable purpose", "The grant is a taxable expenditure because the foundation did not exercise expenditure responsibility over grants to non-501(c)(3) organizations", "The grant is prohibited entirely because private foundations cannot make grants to 501(c)(4) organizations", "The grant is taxable only if the 501(c)(4) uses the funds for lobbying"]'::jsonb, 1, 'Under Section 4945(d)(4), grants by a private foundation to organizations other than 501(c)(3) public charities are taxable expenditures unless the foundation exercises expenditure responsibility under Section 4945(h). Expenditure responsibility requires the foundation to ensure the funds are used for charitable purposes. Choice A is incorrect because the charitable nature of the recipient''s work does not eliminate the expenditure responsibility requirement for non-501(c)(3) grantees.', 'medium', 2),

-- Q16: medium / L3 — NOL deduction for UBIT
(3, 'Tax-Exempt Organizations', 'Pioneer Youth Services, a 501(c)(3), has the following unrelated business results over three years: Year 1 net UBI loss of ($40,000), Year 2 net UBI loss of ($15,000), and Year 3 gross UBI of $120,000 with $50,000 in directly connected expenses. After applying the $1,000 specific deduction and available NOL carryforwards, what is Pioneer''s Year 3 unrelated business taxable income?', '["$69,000", "$24,000", "$14,000", "$0"]'::jsonb, 2, 'Under Section 512(b)(6), net operating losses from unrelated business activities may be carried forward and deducted against future UBI. Year 3 UBI before NOL is $120,000 minus $50,000 expenses minus $1,000 specific deduction = $69,000. Applying the $55,000 NOL carryforward ($40,000 + $15,000) reduces UBTI to $14,000. Choice A incorrectly ignores the NOL carryforward deduction, which is computed using only unrelated business income items.', 'medium', 3),

-- Q17: hard / L4 — Section 4940 net investment income tax computation
(3, 'Tax-Exempt Organizations', 'Monarch Charitable Trust, a private foundation, has the following investment activity: $300,000 in dividend income, $200,000 in capital gains from stock sales, $80,000 in interest income, and $40,000 in investment management expenses. Under Section 4940, what is the excise tax on net investment income?', '["$5,278 (1.39% of $380,000, excluding capital gains)", "$8,062 (1.39% of $580,000 gross investment income without deducting expenses)", "$7,506 (1.39% of $540,000 net investment income after deducting management expenses)", "$7,920 (1.39% of dividends and capital gains only, net of expenses)"]'::jsonb, 2, 'Under Section 4940, the excise tax is 1.39% of net investment income, which includes dividends, interest, rents, royalties, and capital gains, less ordinary and necessary expenses. Net investment income is $580,000 minus $40,000 = $540,000, yielding a tax of $7,506. Choice B is incorrect because Section 4940 allows deduction of investment management expenses in computing net investment income before applying the 1.39% rate.', 'hard', 4),

-- Q18: easy / L1 — Form 990 filing deadline
(3, 'Tax-Exempt Organizations', 'What is the filing deadline for Form 990 for a calendar-year tax-exempt organization?', '["March 15 of the following year", "April 15 of the following year", "June 15 of the following year", "May 15 of the following year"]'::jsonb, 3, 'Under IRC Section 6033, the Form 990 filing deadline is the 15th day of the 5th month after the end of the organization''s tax year. For calendar-year organizations, this is May 15. Choice A is incorrect because March 15 is the deadline for partnership and S corporation returns, not exempt organization returns.', 'easy', 1),

-- Q19: easy / L1 — Private inurement prohibition definition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition under Section 501(c)(3) prevent?', '["Tax-exempt organizations from earning any revenue", "Exempt organizations from conducting any business activities", "Net earnings of the organization from benefiting any private shareholder or individual", "Tax-exempt organizations from hiring paid employees"]'::jsonb, 2, 'Under Section 501(c)(3), the private inurement prohibition prevents any part of the organization''s net earnings from inuring to the benefit of a private shareholder or individual — meaning insiders such as founders, officers, or directors. Choice B is incorrect because exempt organizations may conduct business activities; the restriction is on improper diversion of earnings to insiders, not on earning revenue.', 'easy', 1),

-- Q20: hard / L4 — Expenditure responsibility requirements
(3, 'Tax-Exempt Organizations', 'Atlas Community Foundation, a private foundation, wants to make a $250,000 grant to Global Aid Network, a foreign nonprofit without IRS recognition as a 501(c)(3). The foundation''s counsel advises that the grant may proceed under expenditure responsibility. Evaluate what expenditure responsibility requires and identify the consequence of noncompliance.', '["The foundation must execute a written grant agreement, monitor use of funds, obtain annual reports from the grantee, and report on Form 990-PF; failure makes the grant a taxable expenditure under Section 4945", "The foundation must obtain IRS pre-approval for the grant and file Form 1023 on behalf of the grantee", "The foundation must verify the grantee is a government entity and report the grant on Schedule B of Form 990-PF", "The foundation need only ensure the grant amount is below 5% of its annual distributions"]'::jsonb, 0, 'Under Section 4945(h), expenditure responsibility requires the foundation to exert all reasonable efforts to establish adequate procedures: a written grant agreement limiting use to charitable purposes, regular reports from the grantee, and reporting on Form 990-PF. Failure to exercise expenditure responsibility makes the grant a taxable expenditure under Section 4945(d)(4), triggering a 20% excise tax. Choice B is incorrect — IRS pre-approval is not required; the foundation self-monitors compliance.', 'hard', 4),

-- Q21: easy / L2 — Schedule J compensation disclosure
(3, 'Tax-Exempt Organizations', 'Starlight Foundation, a 501(c)(3) filing Form 990, pays its executive director $250,000 and its chief financial officer $180,000. On which Form 990 schedule must the organization report detailed compensation information for these officers?', '["Schedule A — Public Charity Status and Public Support", "Schedule B — Schedule of Contributors", "Schedule J — Compensation Information", "Schedule D — Supplemental Financial Statements"]'::jsonb, 2, 'Schedule J of Form 990 requires disclosure of compensation information for the organization''s officers, directors, trustees, key employees, and highest-compensated employees. This schedule details base compensation, bonus and incentive pay, and other reportable compensation. Choice B is incorrect because Schedule B reports contributor information (which is confidential), not employee compensation.', 'easy', 2),

-- Q22: medium / L2 — Form 8868 extension for Form 990
(3, 'Tax-Exempt Organizations', 'Horizon Arts Foundation, a calendar-year 501(c)(3), realizes it cannot complete its Form 990 by the May 15 deadline. How can the foundation obtain additional time, and for how long?', '["File a written letter to the IRS requesting a 3-month extension", "No extension is available; the foundation must file by May 15 or face automatic revocation", "Request a 12-month extension by filing Form 2758", "File Form 8868 to receive an automatic extension of up to 6 months"]'::jsonb, 3, 'Under IRC Section 6081, tax-exempt organizations may obtain an automatic extension of up to 6 months by filing Form 8868 by the original due date. For a calendar-year organization, this extends the deadline from May 15 to November 15. Choice B is incorrect because extensions are available — automatic revocation only occurs after three consecutive years of complete non-filing, not for a single late filing with an extension.', 'medium', 2),

-- Q23: medium / L2 — Failure-to-file penalty rates
(3, 'Tax-Exempt Organizations', 'Eastwood Community Center, a 501(c)(3) with gross receipts of $400,000, files its Form 990 sixty days late without reasonable cause. Under the penalty provisions, what is the daily penalty rate for late filing?', '["$10 per day up to $5,000", "$20 per day up to the lesser of $10,500 or 5% of gross receipts", "$50 per day up to $25,000", "$100 per day up to $53,000"]'::jsonb, 1, 'Under IRC Section 6652(c)(1)(A), the penalty for late filing of Form 990 is $20 per day (up to the lesser of $10,500 or 5% of gross receipts) for organizations with gross receipts under $1,186,000. Since Eastwood has $400,000 in gross receipts, the $20/day rate applies. Choice D is incorrect because the $100/day rate applies only to larger organizations with gross receipts of $1,186,000 or more, not to organizations of Eastwood''s size.', 'medium', 2),

-- Q24: hard / L4 — Gross receipts test (Section 509(a)(2))
(3, 'Tax-Exempt Organizations', 'Lakeside Nature Center, a 501(c)(3), receives $500,000 in total support: $120,000 from individual contributions, $200,000 in admission fees from educational programs, $100,000 from government grants, and $80,000 from investment income. Evaluate whether Lakeside qualifies as a public charity under the Section 509(a)(2) gross receipts test.', '["Yes, because more than one-third of support comes from contributions, grants, and exempt-function gross receipts, and investment income does not exceed one-third", "No, because admission fees of $200,000 are classified as unrelated business income", "No, because investment income of $80,000 exceeds the permissible 10% threshold", "Yes, but only if the organization also passes the Section 509(a)(1) one-third support test"]'::jsonb, 0, 'Under Section 509(a)(2), an organization qualifies as a public charity if it receives more than one-third of support from contributions, membership fees, and related exempt-function gross receipts, and not more than one-third from investment income and UBTI. Lakeside''s qualifying support is $420,000/$500,000 (84%), and investment income is $80,000/$500,000 (16%). Both tests are met. Choice C is incorrect because the investment income threshold under 509(a)(2) is one-third (33.3%), not 10%.', 'hard', 4),

-- Q25: easy / L1 — Operational test requirement
(3, 'Tax-Exempt Organizations', 'What does the operational test require for a 501(c)(3) organization?', '["The organization must be incorporated in the state where it operates", "The organization must have at least five board members", "The organization must distribute all revenues annually", "The organization must be operated primarily for one or more exempt purposes"]'::jsonb, 3, 'Under Section 501(c)(3), the operational test requires that an organization be operated primarily (exclusively in the statutory language, interpreted as primarily) for one or more exempt purposes such as charitable, educational, or religious activities. Choice C is incorrect because 501(c)(3) organizations are not required to distribute all revenues annually — that requirement (at 5% of assets) applies only to private foundations under Section 4942.', 'easy', 1),

-- Q26: medium / L3 — Section 4958 organization manager tax ($20,000 cap)
(3, 'Tax-Exempt Organizations', 'Maple Ridge Community Services, a 501(c)(3), provides its chief development officer a $400,000 retention bonus that the IRS determines constitutes a $250,000 excess benefit. The board chair approved the bonus knowing comparable compensation did not support it and without obtaining an independent study. Under Section 4958, what is the excise tax on the board chair as an organization manager?', '["$62,500 (25% of the excess benefit)", "$500,000 (200% of the excess benefit)", "$20,000 (10% of the excess benefit, capped at $20,000 per transaction)", "$25,000 (10% of the excess benefit with no cap)"]'::jsonb, 2, 'Under Section 4958(a)(2), an organization manager who knowingly participates in an excess benefit transaction is subject to a tax of 10% of the excess benefit, up to a maximum of $20,000 per transaction. Here, 10% of $250,000 = $25,000, but the $20,000 cap applies. Choice D is incorrect because it omits the statutory $20,000 per-transaction cap on the manager''s excise tax.', 'medium', 3),

-- Q27: easy / L1 — Section 4958 initial tax rate (25% on disqualified person)
(3, 'Tax-Exempt Organizations', 'What is the initial excise tax rate imposed on a disqualified person who receives an excess benefit from a 501(c)(3) organization under Section 4958?', '["10% of the excess benefit", "25% of the excess benefit", "50% of the excess benefit", "200% of the excess benefit"]'::jsonb, 1, 'Under Section 4958(a)(1), the initial excise tax on a disqualified person who receives an excess benefit is 25% of the excess benefit amount. The 200% additional tax applies only if the disqualified person fails to correct the excess benefit transaction within the taxable period. Choice A is incorrect because the 10% rate is the tax imposed on an organization manager who knowingly participates, not on the disqualified person receiving the excess benefit.', 'easy', 1),

-- Q28: medium / L2 — Reinstatement after automatic revocation
(3, 'Tax-Exempt Organizations', 'River Bend Outreach, a 501(c)(3), had its tax-exempt status automatically revoked after failing to file Form 990 for three consecutive years. What must River Bend do to regain its 501(c)(3) status?', '["Simply file the three missed Form 990 returns and the status is automatically restored", "Appeal the revocation to the U.S. Tax Court within 90 days", "Wait five years and the IRS will automatically restore the exemption", "Apply for reinstatement by filing a new Form 1023 or Form 1023-EZ with the IRS"]'::jsonb, 3, 'Under IRC Section 6033(j), after automatic revocation for three consecutive years of non-filing, an organization must apply for reinstatement by filing a new exemption application (Form 1023 or Form 1023-EZ) and paying the applicable user fee per Revenue Procedure 2014-11. Retroactive reinstatement may be available under certain conditions. Choice A is incorrect because filing delinquent returns alone does not restore exempt status — a new application is required.', 'medium', 2),

-- Q29: medium / L2 — Section 4943 combined holdings with disqualified persons
(3, 'Tax-Exempt Organizations', 'Parkside Family Foundation, a private foundation, owns 12% of the voting stock of Evergreen Corp. The foundation''s disqualified persons own an additional 15% of Evergreen''s voting stock. Under Section 4943, does the foundation have excess business holdings?', '["Yes, because the combined holdings of 27% exceed the 20% permitted holding", "No, because the foundation''s direct holding of 12% is below the 20% limit", "No, because the 20% limit applies only to the foundation''s holdings, not the combined total", "Yes, but only if the foundation has held the stock for more than five years"]'::jsonb, 0, 'Under Section 4943, the combined holdings of a private foundation and its disqualified persons in a business enterprise cannot exceed 20% of voting stock (assuming unrelated third parties have effective control). Here, the combined 27% (12% + 15%) exceeds the 20% limit by 7%, creating excess business holdings subject to a 10% initial excise tax. Choice B is incorrect because Section 4943 aggregates holdings of the foundation and all disqualified persons.', 'medium', 2),

-- Q30: easy / L1 — Private foundation presumption (Section 509)
(3, 'Tax-Exempt Organizations', 'Under Section 509, how are all newly recognized 501(c)(3) organizations initially classified?', '["As public charities until they fail the public support test", "As private foundations unless they demonstrate they qualify as public charities", "As supporting organizations until they obtain independent funding", "As tax-exempt but unclassified until they file their first Form 990"]'::jsonb, 1, 'Under Section 509(a), every 501(c)(3) organization is presumed to be a private foundation unless it affirmatively demonstrates it qualifies as a public charity under one of the statutory exceptions (e.g., the one-third public support test, church/school/hospital status, or supporting organization). Choice A is incorrect because it reverses the default presumption — the burden is on the organization to prove public charity status, not the other way around.', 'easy', 1)
;

COMMIT;
